def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 7]
    if len(points) >= 2:
        points.sort()
        (r1, c1), (r2, c2) = points[-2:]
        dr, dc = r2 - r1, c2 - c1
        if abs(dr) == abs(dc) and dr != 0:
            r, c = r2 + dr, c2 + dc
            while 0 <= r < len(out) and 0 <= c < len(out[0]):
                out[r][c] = 7
                r, c = r + dr, c + dc
    return out

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    for r in range(h - 1):
        for c in range(w):
            for dc in (-1, 1):
                nc = c + dc
                if not (0 <= nc < w):
                    continue
                color = grid[r][c]
                if color == background or grid[r + 1][nc] != color:
                    continue
                rr, cc = r + 2, nc + dc
                while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == background:
                    out[rr][cc] = color
                    rr += 1
                    cc += dc
    return out
